function errorPercent(requests, errors) {
  if (requests === 0) return 0;
  return (errors * 100) / requests;
}

function exposedRequests(total, percent) {
  return Math.round((total * percent) / 100);
}

function totalCanaryMinutes(durations) {
  let total = 0;
  for (const d of durations) total += d;
  return total;
}

function isAboveLimit(percent, limit) {
  return percent > limit;
}

function nextStage(stages, current) {
  for (const s of stages) {
    if (s > current) return s;
  }
  return null;
}

function firstUnhealthyStage(stages, maxErrorPercent) {
  for (const stage of stages) {
    if (stage.requests === 0) continue;
    if (stage.errors * 100 > maxErrorPercent * stage.requests) {
      return stage.trafficPercent;
    }
  }
  return null;
}

function releaseOutcome(stages, maxErrorPercent) {
  for (const stage of stages) {
    if (stage.requests === 0) continue;
    if (stage.errors * 100 > maxErrorPercent * stage.requests) {
      return "rolled-back-at-" + stage.trafficPercent;
    }
  }
  return "shipped";
}

function minutesBeforeRollback(stages, maxErrorPercent) {
  let minutes = 0;
  for (const stage of stages) {
    minutes += stage.durationMinutes;
    if (stage.requests !== 0 && stage.errors * 100 > maxErrorPercent * stage.requests) {
      return minutes;
    }
  }
  return minutes;
}
